-- The rules the global registry rolls new barcodes by: a copy of REGISTRY_RULES
-- (lib/barcodeRegistry.ts), written by `npm run registry:rules`. Don't edit by hand.
insert into public.registry_rules (id, rules) values (1, '{"odds":{"creature":40,"weapon":13,"armor":26,"consumable":7,"material":6,"gold":7,"soul_stone":1},"rarity":{"common":40,"uncommon":30,"rare":20,"epic":9,"legendary":1},"consumableRarity":{"common":40,"uncommon":30,"rare":20},"gold":{"min":50,"max":150},"creatures":{"common":["moss_wolf","cave_bat","dust_sprite","rattlebones","thicket_archer","gleamling","plague_rat"],"uncommon":["amber_wasp","rust_beetle","flicker_wisp","shambler","leafblade_scout","flame_imp","rotgut_fly"],"rare":["bellow_toad","crystalback","veilstalker","dustwraith","aurelius","deep_angler","glob"],"epic":["dire_wolf","crystal_golem","the_watcher","mr_shadows","swamp_witch","tunnel_wyrm","dreadpox"],"legendary":["ironhide","hollow_matriarch","void_serpent","storm_phoenix","sylvaran","thunderhead","pale_rider"]},"weapons":["void_scythe","temporal_maul","serrated_fanblade","stormlash_whip","weeping_greatbow","lightning_trident","thunderhead_crossbow","soul_storm","chaos_orb","frostspire_staff","chainbound_aegis","ironfang_guard","basalt_bulwark","aether_shield"],"armors":["frontiers_mail","arrowward_mantle","dragonscale_tunic","colossal_shellarmor","arcane_nullifier","polished_chainbolster","juggernaut_platemail"],"armorSlots":["helmet","chest","legs"],"soulStones":["toxic_skin","haunting_presence","unstoppable_force","perfectionist","trickster","revitalise"]}'::jsonb)
  on conflict (id) do update set rules = excluded.rules, updated_at = now();
